func TestApplyInventoryPreloadRecordV2_Create(t *testing.T) {
	c, mux := testServerWithOpts(t, WithTenantID("t-test"))
	// List and create share the same path — single handler dispatches on method.
	mux.HandleFunc("/pro/v2/inventory-preload/records", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			writeJSON(t, w, http.StatusOK, map[string]any{
				"results":    []any{},
				"totalCount": 0,
			})
		case http.MethodPost:
			writeJSON(t, w, 201, map[string]any{
				"id":   "new-id",
				"href": "/new-id",
			})
		default:
			t.Errorf("unexpected method %s", r.Method)
		}
	})

	id, created, err := c.ApplyInventoryPreloadRecordV2(context.Background(), &InventoryPreloadRecordV2{SerialNumber: "target"})
	if err != nil {
		t.Fatal(err)
	}
	if !created {
		t.Error("expected created = true")
	}
	if id != "new-id" {
		t.Errorf("id = %q, want new-id", id)
	}
}

func TestApplyInventoryPreloadRecordV2_Update(t *testing.T) {
	c, mux := testServerWithOpts(t, WithTenantID("t-test"))
	// List returns a match → resolver succeeds → apply updates.
	mux.HandleFunc("/pro/v2/inventory-preload/records", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			t.Errorf("method = %s, want GET", r.Method)
		}
		writeJSON(t, w, http.StatusOK, map[string]any{
			"results": []map[string]any{
				{"id": "existing-id", "serialNumber": "target"},
			},
			"totalCount": 1,
		})
	})
	mux.HandleFunc("/pro/v2/inventory-preload/records/existing-id", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(t, w, 200, map[string]any{"id": "existing-id"})
	})

	id, created, err := c.ApplyInventoryPreloadRecordV2(context.Background(), &InventoryPreloadRecordV2{SerialNumber: "target"})
	if err != nil {
		t.Fatal(err)
	}
	if created {
		t.Error("expected created = false")
	}
	if id != "existing-id" {
		t.Errorf("id = %q, want existing-id", id)
	}
}
